import { fileURLToPath } from "node:url";

import type { Plugin } from "vite";

import { akariMediaColors } from "./media-colors";

/**
 * The Vite plugins the theme needs while a site is built.
 *
 * A site generated by the CLI writes its own VitePress config, so the theme
 * cannot put these in its own config file; the manifest points at this
 * export instead (see `vite_module` / `vite_export` in docs-theme.json).
 *
 * This module sits at `<src>/.vitepress/theme/`, so the paths the plugin
 * needs are one level up from `.vitepress`.
 */
export function akariVitePlugins(): Plugin[] {
  return [
    akariMediaColors({
      srcDir: fileURLToPath(new URL("../..", import.meta.url)),
      publicDir: fileURLToPath(new URL("../../public", import.meta.url)),
      cacheFile: fileURLToPath(
        new URL("../cache/media-colors.json", import.meta.url),
      ),
    }),
  ];
}
